from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Plan_delete(EmssimCommand):
    def __init__(self, method="plan_delete", timeout=60, rpc_connection_name='localRPC'):
        super(Plan_delete, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Plan_delete, self).on_new_data(**data)
        if "msg" in data:
            if "No plan exists!" in data["msg"]:
                print(data["msg"])
        elif ("status" in data):
            self._ret["status"] = data["status"]
